1	// 首页“房间列表混合记录展示”的界面回归测试。
2	//
3	// 与另外三个浏览器回归文件的分工：
4	//   - ui.test.mjs：创建成功/被拒、成功后列表竞态刷新、名称整理与长度边界；
5	//   - ui-capacity-linkage.test.mjs：游戏规则与人数上限的联动；
6	//   - ui-turn-seconds.test.mjs：每步时间限制的填写、提交与展示；
7	//   - 本文件只盯住“打开首页查看房间列表”：接口返回的数组里混着房间对象与
8	//     null、字符串、数字、布尔值、数组等非对象记录时，用户实际看到的列表。
9	//
10	// 保护的已有行为（本文件不修改任何产品代码，只补回归保障）：
11	//   - 只有 JSON 对象能成为房间行；null、字符串、数字、布尔值、数组一律跳过，
12	//     一条非对象记录不能拖累其他房间（它前后的房间对象都要照常显示），
13	//     也不能让整份列表显示加载失败；
14	//   - 房间行只按对象在返回数组中的相对次序排列，编号、名称、规则中文名
15	//     （五子棋/飞行棋）、人数、时间（0 显示“不限时”）、状态（waiting 显示
16	//     “未开始”）、创建时间沿用现有页面展示；
17	//   - “能否作为房间行”与创建房间时的配置校验无关：对象带额外字段照常展示，
18	//     缺少部分字段（乃至空对象）仍然成行且不计入跳过数量，单元格沿用现有
19	//     兜底显示；
20	//   - 空数组以及内部装着房间对象的数组都只是“一条数组记录”，跳过且不展开；
21	//     空字符串、数字 0、布尔值 false 不能因为内容为空或值为假而漏计；
22	//   - 列表区域必须给出准确跳过条数，并说明原始数据仍保留在服务端，未被删除
23	//     或改写；数组非空但全部被跳过时，说明“没有可展示的房间”与全部跳过的
24	//     数量，不出表格、不显示“还没有房间记录”；只有真正的空数组才显示空列表
25	//     提示且没有跳过警告；
26	//   - 查看列表本身是只读操作：接口返回的原始记录与本地 rooms.json 的数量、
27	//     次序、类型与附带字段保持不变；混排数据下创建房间，原始记录也原样保留，
28	//     新房间作为对象照常追加为最后一行。
29	//
30	// 运行：npm test（需要系统 Chrome，可用 CHROME_PATH 指定路径）。
31	
32	import { test, before, after } from 'node:test';
33	import assert from 'node:assert/strict';
34	import { execFile, spawn } from 'node:child_process';
35	import { mkdtemp, writeFile, readFile, rm } from 'node:fs/promises';
36	import { tmpdir } from 'node:os';
37	import path from 'node:path';
38	import { promisify } from 'node:util';
39	import puppeteer from 'puppeteer-core';
40	
41	const repoRoot = import.meta.dirname;
42	const chromePath = process.env.CHROME_PATH || '/usr/bin/google-chrome';
43	
44	let serverBin;
45	let browser;
46	
47	// 两类正常房间：R1 飞行棋 4 人 30 秒 playing（非 waiting 状态原文展示），
48	// R2 五子棋 2 人 0 秒 waiting（“不限时”“未开始”两个关键中文映射）。
49	// R1 附带 note/tags 额外字段，与其他回归文件一样用于确认附带字段不影响展示。
50	const R1 =
51	  '{"id":"mix-alpha","name":"晨间混播飞行棋","game":"ludo","capacity":4,"turnSeconds":30,' +
52	  '"status":"playing","visibility":"public","createdAt":"2026-02-03T08:30:00Z",' +
53	  '"note":"原样保留","tags":["混排","回归"]}';
54	const R2 =
55	  '{"id":"mix-beta","name":"午夜混播五子棋","game":"gomoku","capacity":2,"turnSeconds":0,' +
56	  '"status":"waiting","visibility":"public","createdAt":"2026-02-04T23:15:00Z"}';
57	// 带额外字段的完整房间：额外字段不得产生新列或影响既有列。
58	const R3_EXTRA =
59	  '{"id":"mix-extra","name":"多字段飞行棋","game":"ludo","capacity":3,"turnSeconds":600,' +
60	  '"status":"waiting","visibility":"public","createdAt":"2026-02-05T12:00:00Z",' +
61	  '"weird":true,"nested":{"rank":1},"tail":[1,2,3]}';
62	// 缺少 turnSeconds/status/visibility/createdAt 的对象：仍是房间行，不计跳过，
63	// 缺字段的单元格沿用页面现有兜底显示。
64	const R4_PARTIAL = '{"id":"mix-partial","name":"缺字段五子棋","game":"gomoku","capacity":2}';
65	// 空对象同样是对象：必须成行、不计跳过，各单元格走兜底。
66	const R5_EMPTY = '{}';
67	
68	// 装在数组里的房间对象：整个数组只算一条非对象记录，绝不能展开成房间行。
69	const INNER_ROOM =
70	  '{"id":"inside-array","name":"数组里的房间不应展开","game":"gomoku","capacity":2,' +
71	  '"turnSeconds":0,"status":"waiting","createdAt":"2026-02-06T00:00:00Z"}';
72	
73	// 全类型混排：9 条非对象记录（含空串/0/false/空数组/装对象的数组）穿插在
74	// 房间对象之间，用来证明非对象记录既不拖累前一个房间，也不拖累后一个房间。
75	const MIXED_RECORDS = [
76	  R1,
77	  'null',
78	  '""',
79	  '"一段普通字符串"',
80	  '0',
81	  '42',
82	  'false',
83	  'true',
84	  '[]',
85	  '[' + INNER_ROOM + ']',
86	  R2,
87	  R3_EXTRA,
88	  R4_PARTIAL,
89	  R5_EMPTY,
90	];
91	const MIXED_SKIPPED = 9;
92	const MIXED_ROW_COUNT = 5;
93	
94	const EMPTY_TEXT = '还没有房间记录。';
95	const SUCCESS_PREFIX = '房间已创建，编号：';
96	
97	before(async () => {
98	  const dir = await mkdtemp(path.join(tmpdir(), 'score-arena-uibin-'));
99	  serverBin = path.join(dir, 'score-arena');
100	  await promisify(execFile)('go', ['build', '-o', serverBin, '.'], { cwd: repoRoot });
101	  browser = await puppeteer.launch({
102	    executablePath: chromePath,
103	    headless: true,
104	    args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage'],
105	  });
106	});
107	
108	after(async () => {
109	  if (browser) await browser.close();
110	  if (serverBin) await rm(path.dirname(serverBin), { recursive: true, force: true });
111	});
112	
113	function startServer(t, dataDir) {
114	  const proc = spawn(
115	    serverBin,
116	    ['serve', '--host', '127.0.0.1', '--port', '0', '--data-dir', dataDir],
117	    { stdio: ['ignore', 'pipe', 'inherit'] },
118	  );
119	  t.after(() => { proc.kill('SIGKILL'); });
120	  return new Promise((resolve, reject) => {
121	    let buf = '';
122	    const timer = setTimeout(() => reject(new Error('等待服务监听地址超时')), 15000);
123	    proc.stdout.on('data', (chunk) => {
124	      buf += chunk.toString();
125	      const m = buf.match(/listening on (http:\/\/\S+)/);
126	      if (m) {
127	        clearTimeout(timer);
128	        resolve(m[1]);
129	      }
130	    });
131	    proc.on('exit', (code) => {
132	      clearTimeout(timer);
133	      reject(new Error(`服务在输出监听地址前退出，退出码 ${code}`));
134	    });
135	  });
136	}
137	
138	// seedRecords 以原始 JSON 片段写 rooms.json，返回写入的确切文本，
139	// 供“读取不改写文件”的逐字节比对使用。
140	async function seedRecords(dataDir, records) {
141	  const content = '[\n' + records.join(',\n') + '\n]\n';
142	  await writeFile(path.join(dataDir, 'rooms.json'), content);
143	  return content;
144	}
145	
146	async function setupMixedPage(t, records) {
147	  const dataDir = await mkdtemp(path.join(tmpdir(), 'score-arena-uidata-'));
148	  t.after(() => rm(dataDir, { recursive: true, force: true }));
149	  const seedText = await seedRecords(dataDir, records);
150	  const baseURL = await startServer(t, dataDir);
151	  const page = await browser.newPage();
152	  t.after(() => page.close());
153	  await page.goto(baseURL, { waitUntil: 'load' });
154	  return { page, baseURL, dataDir, seedText };
155	}
156	
157	function waitForRowCount(page, n) {
158	  return page.waitForFunction(
159	    (want) => document.querySelectorAll('#list-area table tbody tr').length === want,
160	    { timeout: 10000 },
161	    n,
162	  );
163	}
164	
165	// readRows 读取每行单元格文本、创建时间 title（原始 ISO）与状态徽标文本。
166	function readRows(page) {
167	  return page.$$eval('#list-area table tbody tr', (trs) =>
168	    trs.map((tr) => {
169	      const tds = [...tr.querySelectorAll('td')];
170	      return {
171	        cells: tds.map((td) => td.textContent),
172	        timeTitle: tds[6] ? tds[6].getAttribute('title') : null,
173	        badge: tds[5] && tds[5].querySelector('.badge')
174	          ? tds[5].querySelector('.badge').textContent
175	          : null,
176	      };
177	    }),
178	  );
179	}
180	
181	function readListArea(page) {
182	  return page.evaluate(() => ({
183	    text: document.getElementById('list-area').textContent,
184	    hasTable: !!document.querySelector('#list-area table'),
185	    rowCount: document.querySelectorAll('#list-area table tbody tr').length,
186	    skipText: document.querySelector('#list-area .skip-notice')
187	      ? document.querySelector('#list-area .skip-notice').textContent
188	      : null,
189	    skipCount: document.querySelectorAll('#list-area .skip-notice').length,
190	    errorText: document.querySelector('#list-area .list-error')
191	      ? document.querySelector('#list-area .list-error').textContent
192	      : null,
193	    emptyTexts: [...document.querySelectorAll('#list-area .empty')].map((el) => el.textContent),
194	  }));
195	}
196	
197	function waitForSkipNotice(page) {
198	  return page.waitForFunction(
199	    () => !!document.querySelector('#list-area .skip-notice'),
200	    { timeout: 10000 },
201	  );
202	}
203	
204	function waitForEmptyTip(page) {
205	  return page.waitForFunction(
206	    () => !!document.querySelector('#list-area .empty'),
207	    { timeout: 10000 },
208	  );
209	}
210	
211	async function readServerRooms(baseURL) {
212	  const res = await fetch(baseURL + '/api/rooms');
213	  assert.equal(res.status, 200);
214	  return (await res.json()).rooms;
215	}
216	
217	// 填写并提交五子棋表单（人数固定 2 人由页面自动选中）。
218	async function fillGomokuForm(page, name, turnSeconds) {
219	  await page.type('#name', name);
220	  await page.select('#game', 'gomoku');
221	  await page.waitForFunction(
222	    () => !document.getElementById('capacity').disabled &&
223	      document.getElementById('capacity').value === '2',
224	    { timeout: 5000 },
225	  );
226	  await page.type('#turnSeconds', String(turnSeconds));
227	  await page.click('#submit');
228	}
229	
230	function nextCreated(page) {
231	  return new Promise((resolve, reject) => {
232	    page.on('response', (resp) => {
233	      if (resp.request().method() === 'POST' && resp.url().endsWith('/api/rooms')) {
234	        resp.json().then(resolve, reject);
235	      }
236	    });
237	  });
238	}
239	
240	function waitForMessageKind(page, kind) {
241	  return page.waitForFunction(
242	    (cls) => document.getElementById('form-msg').classList.contains(cls),
243	    { timeout: 10000 },
244	    kind,
245	  );
246	}
247	
248	// 全类型混排：所有房间对象按相对次序成行，9 条非对象记录（含空串/0/false/
249	// 空数组/装对象的数组）全部跳过且计数准确；跳过内容不成行、不展开、不导致
250	// 加载失败；跳过提示同时说明原始数据仍保留在服务端。
251	test('混合记录：房间对象全部按相对次序展示，非对象记录全部跳过并给出准确条数与保留说明', { timeout: 60000 }, async (t) => {
252	  const { page } = await setupMixedPage(t, MIXED_RECORDS);
253	
254	  await waitForRowCount(page, MIXED_ROW_COUNT);
255	  await waitForSkipNotice(page);
256	  const list = await readListArea(page);
257	
258	  // 只有对象成为房间行：5 个对象（含缺字段对象与空对象），非对象记录不展开成行。
259	  assert.equal(list.rowCount, MIXED_ROW_COUNT, '只有 JSON 对象应成为房间行');
260	  assert.equal(list.hasTable, true, '存在可展示房间时应显示房间表格');
261	
262	  // 跳过条数准确：null、空串、普通字符串、0、42、false、true、空数组、
263	  // 装对象的数组各算一条，共 9 条。
264	  assert.equal(list.skipCount, 1, '列表区域应只有一条跳过提示');
265	  assert.equal(
266	    list.skipText,
267	    '有 ' + MIXED_SKIPPED + ' 条房间记录无法作为房间显示，已跳过；' +
268	      '原始数据仍保留在服务端，未被删除或改写。',
269	    '跳过提示的条数或保留说明不正确',
270	  );
271	
272	  // 跳过的内容不能导致整份列表失败。
273	  assert.equal(list.errorText, null, '存在非对象记录不应导致列表加载失败');
274	
275	  // 数组里的房间对象不能被展开：其编号与名称不出现在列表区域，
276	  // 普通字符串等原始内容也不应作为房间文本上屏。
277	  assert.ok(!list.text.includes('inside-array'), '数组内的房间记录不能被展开成房间行');
278	  assert.ok(!list.text.includes('数组里的房间不应展开'), '数组内容不能上屏');
279	  assert.ok(!list.text.includes('一段普通字符串'), '被跳过的字符串不能上屏');
280	
281	  const rows = await readRows(page);
282	  // 房间行严格按对象在返回数组中的相对次序排列：
283	  // R1（最前）→ R2（跳过段之后）→ R3 → R4 → R5。
284	  assert.deepEqual(
285	    rows.map((r) => r.cells[0]),
286	    ['mix-alpha', 'mix-beta', 'mix-extra', 'mix-partial', ''],
287	    '房间行的排列次序应与对象在返回列表中的相对次序一致',
288	  );
289	
290	  // R1：飞行棋中文名、4 人、30 秒、非 waiting 状态原文显示、创建时间保留原始 ISO。
291	  assert.deepEqual(rows[0].cells.slice(0, 6), [
292	    'mix-alpha', '晨间混播飞行棋', '飞行棋', '4 人', '30 秒', 'playing',
293	  ]);
294	  assert.equal(rows[0].badge, 'playing', '未知状态沿用原文展示');
295	  assert.equal(rows[0].timeTitle, '2026-02-03T08:30:00Z');
296	  assert.match(rows[0].cells[6], /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/);
297	
298	  // R2：五子棋中文名、0 秒显示“不限时”、waiting 显示“未开始”。
299	  assert.deepEqual(rows[1].cells.slice(0, 6), [
300	    'mix-beta', '午夜混播五子棋', '五子棋', '2 人', '不限时', '未开始',
301	  ]);
302	  assert.equal(rows[1].badge, '未开始', 'waiting 状态应以徽标显示“未开始”');
303	  assert.equal(rows[1].timeTitle, '2026-02-04T23:15:00Z');
304	
305	  // R3：额外字段不产生新列、不改变既有列；600 秒端点正常显示。
306	  assert.deepEqual(rows[2].cells.slice(0, 6), [
307	    'mix-extra', '多字段飞行棋', '飞行棋', '3 人', '600 秒', '未开始',
308	  ]);
309	  assert.equal(rows[2].cells.length, 7, '额外字段不能导致列数变化');
310	
311	  // R4：缺字段对象仍是房间行（不计跳过），缺的单元格沿用现有兜底显示。
312	  assert.deepEqual(rows[3].cells, [
313	    'mix-partial', '缺字段五子棋', '五子棋', '2 人', 'undefined 秒', '', '',
314	  ], '缺字段对象的单元格应沿用现有兜底显示');
315	  assert.equal(rows[3].badge, '');
316	  // 现有兜底：缺 createdAt 时单元格文本为空，title 属性被 DOM 序列化为 "undefined"。
317	  assert.equal(rows[3].timeTitle, 'undefined');
318	
319	  // R5：空对象也是对象，同样成行且不计跳过，各单元格走兜底。
320	  assert.deepEqual(rows[4].cells, [
321	    '', '', '', ' 人', 'undefined 秒', '', '',
322	  ], '空对象应作为房间行并沿用现有兜底显示');
323	  assert.equal(rows[4].badge, '');
324	  assert.equal(rows[4].timeTitle, 'undefined');
325	});
326	
327	// 数组非空但所有元素都是非对象（且刻意包含空串、0、false、空数组这些
328	// “空/假值”）：全部计入跳过，页面说明没有可展示的房间与全部跳过数量，
329	// 不出房间表格，也不显示“还没有房间记录”，更不是加载失败。
330	test('全部跳过：说明没有可展示房间与跳过总数，无表格、无空列表提示、无加载失败', { timeout: 60000 }, async (t) => {
331	  const allSkipped = ['null', '""', '0', 'false', '[]'];
332	  const { page } = await setupMixedPage(t, allSkipped);
333	
334	  await waitForSkipNotice(page);
335	  // 给页面足够时间，确认不会迟来一个表格或空提示。
336	  await new Promise((resolve) => setTimeout(resolve, 300));
337	  const list = await readListArea(page);
338	
339	  assert.equal(
340	    list.skipText,
341	    '没有可展示的房间。本次返回的房间记录中有 5 条无法作为房间显示，已全部跳过；' +
342	      '原始数据仍保留在服务端，未被删除或改写。',
343	    '全部跳过时应说明没有可展示的房间以及准确的全部跳过数量',
344	  );
345	  assert.equal(list.skipCount, 1);
346	  assert.equal(list.rowCount, 0, '非对象记录不能成为房间行');
347	  assert.equal(list.hasTable, false, '没有可展示房间时不应出现房间表格');
348	  assert.deepEqual(list.emptyTexts, [], '全部跳过时不应显示“还没有房间记录”');
349	  assert.ok(!list.text.includes(EMPTY_TEXT), '全部跳过时不能出现空列表文案');
350	  assert.equal(list.errorText, null, '跳过记录不是加载失败');
351	});
352	
353	// 只有真正的空数组才显示空列表提示，且没有任何跳过警告。
354	test('真正的空数组：显示空列表提示，没有跳过警告与表格', { timeout: 60000 }, async (t) => {
355	  const { page } = await setupMixedPage(t, []);
356	
357	  await waitForEmptyTip(page);
358	  const list = await readListArea(page);
359	  assert.deepEqual(list.emptyTexts, [EMPTY_TEXT], '只有真正的空数组才显示空列表提示');
360	  assert.equal(list.skipText, null, '空数组不应产生跳过警告');
361	  assert.equal(list.hasTable, false);
362	  assert.equal(list.errorText, null);
363	});
364	
365	// 查看混合列表是只读操作：接口返回的原始记录保持数量、次序、原始类型与
366	// 附带字段；本地 rooms.json 逐字节不变。刷新页面再看一次结果完全一致。
367	test('查看混合列表后：接口原始记录与本地文件的数量、次序、类型、附带字段保持不变', { timeout: 60000 }, async (t) => {
368	  const { page, baseURL, dataDir, seedText } = await setupMixedPage(t, MIXED_RECORDS);
369	
370	  await waitForRowCount(page, MIXED_ROW_COUNT);
371	  await waitForSkipNotice(page);
372	
373	  // 接口返回与种子完全一致的结构（含 null/字符串/数字/布尔/数组的原始类型，
374	  // 以及对象的附带字段）。
375	  const expected = [
376	    JSON.parse(R1), null, '', '一段普通字符串', 0, 42, false, true, [], [JSON.parse(INNER_ROOM)],
377	    JSON.parse(R2), JSON.parse(R3_EXTRA), JSON.parse(R4_PARTIAL), {},
378	  ];
379	  const roomsOnce = await readServerRooms(baseURL);
380	  assert.deepEqual(roomsOnce, expected, '接口返回的原始记录（数量、次序、类型、附带字段）被改动');
381	
382	  // 刷新页面再查看一次：用户看到的行与跳过提示保持一致。
383	  await page.reload({ waitUntil: 'load' });
384	  await waitForRowCount(page, MIXED_ROW_COUNT);
385	  const list = await readListArea(page);
386	  assert.equal(list.rowCount, MIXED_ROW_COUNT);
387	  assert.ok(list.skipText && list.skipText.includes('' + MIXED_SKIPPED));
388	  assert.deepEqual(
389	    (await readRows(page)).map((r) => r.cells[0]),
390	    ['mix-alpha', 'mix-beta', 'mix-extra', 'mix-partial', ''],
391	  );
392	
393	  // 再次查询仍与原始结构一致；本地文件逐字节保持种子内容（读取不触发改写）。
394	  assert.deepEqual(await readServerRooms(baseURL), expected, '再次查看后接口记录被改动');
395	  const onDisk = await readFile(path.join(dataDir, 'rooms.json'), 'utf8');
396	  assert.equal(onDisk, seedText, '查看列表不应改写本地保存的原始记录');
397	});
398	
399	// 混合数据下创建公开房间的既有行为不变：原始的非对象记录与附带字段原样保留
400	// 在原位置，新房间作为对象追加为最后一行，跳过数量不变、提示仍在。
401	test('混合记录下创建房间：原始记录原位保留，新房间追加为最后一行，跳过计数不变', { timeout: 60000 }, async (t) => {
402	  const seed = [R1, 'null', '"误入的字符串"', 'false', R2];
403	  const { page, baseURL } = await setupMixedPage(t, seed);
404	
405	  await waitForRowCount(page, 2);
406	  await waitForSkipNotice(page);
407	  let list = await readListArea(page);
408	  assert.equal(
409	    list.skipText,
410	    '有 3 条房间记录无法作为房间显示，已跳过；原始数据仍保留在服务端，未被删除或改写。',
411	  );
412	
413	  const createdPromise = nextCreated(page);
414	  await fillGomokuForm(page, '混排中新建的房间', 0);
415	  await waitForMessageKind(page, 'ok');
416	  const created = await createdPromise;
417	  assert.ok(created.id, '创建结果应包含新房间编号');
418	
419	  // 列表刷新后：原有两个房间与新房间共 3 行，非对象记录仍跳过同样的 3 条。
420	  await waitForRowCount(page, 3);
421	  list = await readListArea(page);
422	  assert.equal(list.rowCount, 3);
423	  assert.equal(
424	    list.skipText,
425	    '有 3 条房间记录无法作为房间显示，已跳过；原始数据仍保留在服务端，未被删除或改写。',
426	    '创建房间不应改变跳过条数或保留说明',
427	  );
428	  const rows = await readRows(page);
429	  assert.deepEqual(
430	    rows.map((r) => r.cells[0]),
431	    ['mix-alpha', 'mix-beta', created.id],
432	    '新房间应作为对象追加在原有房间之后，原始次序不变',
433	  );
434	  assert.equal(rows[2].cells[1], created.name);
435	  assert.equal(rows[2].cells[4], '不限时');
436	  assert.equal(rows[2].badge, '未开始');
437	
438	  // 服务端记录：5 条原始记录原位保留（含类型与附带字段），新对象追加在最后。
439	  const serverRooms = await readServerRooms(baseURL);
440	  assert.equal(serverRooms.length, 6, '原始记录一条不少，另加新建房间');
441	  assert.deepEqual(serverRooms.slice(0, 5), [
442	    JSON.parse(R1), null, '误入的字符串', false, JSON.parse(R2),
443	  ], '原始记录的数量、次序、类型与附带字段必须原位保留');
444	  assert.equal(serverRooms[5].id, created.id, '新房间应保存在最后');
445	});
